/// MOOSE ontology-agnostic. Scores are raw BM25 values: unnormalized,
/// corpus-relative, and **not** in `[0, 1]`. Callers should rank and take
/// top-k results, and must not apply the fixed absolute floors used by the
/// entity gazetteer. All literal values for each supplied predicate are
/// included; this API does not perform language-tag selection.
pub fn search_records(
    &self,
    query: &str,
    class_iris: &[String],
    store: &Store,
    data_graphs: &[String],
    text_fields: &[(&str, f32)],
    limit: usize,
) -> Vec<IndexMatch> {
    if limit == 0 {
        return Vec::new();
    }
    let query_terms = query_terms(query);
    if query_terms.is_empty() {
        return Vec::new();
    }
    let query_term_set: HashSet<&str> = query_terms.iter().map(String::as_str).collect();
    let valid_text_fields = valid_record_text_fields(text_fields);
    if valid_text_fields.is_empty() {
        return Vec::new();
    }

    let candidates = collect_record_candidates(class_iris, store, data_graphs);
    if candidates.is_empty() {
        return Vec::new();
    }

    // TODO: cache corpus stats if record corpora grow beyond the expected
    // hundreds-to-low-thousands size.
    let docs: Vec<RecordDocument> = candidates
        .into_iter()
        .filter_map(|candidate| {
            build_record_document(
                candidate,
                store,
                data_graphs,
                &valid_text_fields,
                &query_terms,
                &query_term_set,
            )
        })
        .collect();

    let mut results = score_record_documents(docs, &query_terms);
    results.sort_by(|a, b| b.score.total_cmp(&a.score));
    results.truncate(limit);
    results
}

/// Invalidate all cached indexes.
pub fn invalidate_all(&self) {
    let mut inner = self.inner.write().unwrap_or_else(|e| {
        warn!("EntityIndexCache write lock was poisoned, recovering");
        e.into_inner()
    });
    inner.indexes.clear();
    inner.access_order.clear();
    inner.label_sets.clear();
    inner.label_order.clear();
    inner.global_epoch = inner.global_epoch.wrapping_add(1);
    debug!("Entity index cache: invalidated all entries");
}

/// Invalidate indexes that include a specific graph.
pub fn invalidate_graph(&self, graph_iri: &str) {
    let mut inner = self.inner.write().unwrap_or_else(|e| {
        warn!("EntityIndexCache write lock was poisoned, recovering");
        e.into_inner()
    });
    let to_remove: Vec<String> = inner
        .indexes
        .iter()
        .filter(|(_, idx)| idx.data_graphs.contains(graph_iri))
        .map(|(k, _)| k.clone())
        .collect();
    for key in &to_remove {
        inner.indexes.remove(key);
        inner.access_order.retain(|k| k != key);
    }
    let removed_label_set = inner.label_sets.remove(graph_iri).is_some();
    if removed_label_set {

        Err(e) => Ok(tool_error(format!("failed to relate: {e}"))),
    }
}

/// Ask a natural-language question over the project knowledge graph.
#[tool(
    description = "Ask a natural-language question over the project knowledge graph. Returns an answer plus a symbolic reasoning trace."
)]
async fn query(
    &self,
    Parameters(args): Parameters<QueryArgs>,
) -> Result<CallToolResult, McpError> {
    let question = args.question.trim();
    if question.is_empty() {
        return Ok(tool_error("`question` must not be empty"));
    }
    match graph::query(&self.state, question).await {
        Ok(r) => Ok(tool_ok(format!(
            "{}\n\n(confidence: {})\n\n--- reasoning trace ---\n{}",
            r.answer, r.confidence, r.trace
        ))),
        Err(e) => Ok(tool_error(format!("query failed: {e}"))),
    }
}

/// Retrieve recorded project knowledge relevant to a topic (or all of it).
#[tool(
    description = "Retrieve curated, authoritative project knowledge (architectural decisions, constraints, lessons, patterns, requirements) relevant to a topic — the maintainers' recorded source of truth for this project's decisions and rationale, kept current (superseded entries are excluded by default). Consult it before answering a why-question or choosing an implementation approach, and TRUST it: prefer its recorded answer over re-deriving from the code, and do not re-verify its claims against the source unless explicitly asked. Symbolic — no LLM. Omit the topic to list all recorded knowledge."
)]
async fn get_relevant_context(
    &self,
    Parameters(args): Parameters<GetRelevantContextArgs>,
) -> Result<CallToolResult, McpError> {
    let limit = args.limit.unwrap_or(10).clamp(1, 100);
    let include_history = args.include_history.unwrap_or(false);
    match graph::relevant_context(&self.state, args.topic.as_deref(), limit, include_history) {
        // Distinguish "nothing relevant to this topic" from "nothing recorded
        // at all": after the relevance floor, an empty topic result means no
        // record cleared the bar, not that the graph is empty. Saying so
        // honestly keeps the agent from reading silence as a settled topic.
        Ok(items) if items.is_empty() => {
            let msg = match args
                .topic
                .as_deref()
                .map(str::trim)
                .filter(|t| !t.is_empty())
            {
                Some(t) => format!("No recorded knowledge relevant to \"{t}\"."),
                None => "No recorded knowledge found.".to_string(),
            };
            Ok(tool_ok(msg))
        }
        Ok(items) => Ok(tool_ok(format_context(&items))),
        Err(e) => Ok(tool_error(format!("failed to retrieve context: {e}"))),
    }
}

